-- What a provider's notice tells about a payment (#108; D127 4.4): the amount the venue refunded
-- in its own provider dashboard and where a dispute stands, both as last read back from the
-- provider, never added up from notices (a notice may come twice, late or out of order). Restro
-- never refunds (D125 3.5); it only records what the provider reads back. Generated by drizzle-kit,
-- then this comment added by hand. No data.
--
-- `provider_notices` gains the notice's kind in the platform's words, which picks the worker's
-- handler, and the object it is about. `kind` is NOT NULL with no default: no code has stored a
-- notice yet (the route arrives with this migration), so the table is empty everywhere; if it were
-- not, the migration would stop rather than guess a kind.
ALTER TABLE "restro"."payments" ADD COLUMN "refunded_minor" bigint DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."payments" ADD COLUMN "dispute" text;--> statement-breakpoint
ALTER TABLE "restro"."provider_notices" ADD COLUMN "kind" text NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."provider_notices" ADD COLUMN "object_ref" text;--> statement-breakpoint
ALTER TABLE "restro"."payments" ADD CONSTRAINT "payments_refunded_minor" CHECK ("restro"."payments"."refunded_minor" >= 0 and "restro"."payments"."refunded_minor" <= coalesce("restro"."payments"."captured_minor", 0));--> statement-breakpoint
ALTER TABLE "restro"."payments" ADD CONSTRAINT "payments_dispute" CHECK ("restro"."payments"."dispute" is null or "restro"."payments"."dispute" in ('open', 'won', 'lost'));--> statement-breakpoint
ALTER TABLE "restro"."provider_notices" ADD CONSTRAINT "provider_notices_kind" CHECK ("restro"."provider_notices"."kind" in ('refund', 'dispute', 'other'));--> statement-breakpoint
ALTER TABLE "restro"."provider_notices" ADD CONSTRAINT "provider_notices_object_ref" CHECK ("restro"."provider_notices"."object_ref" is null or "restro"."provider_notices"."object_ref" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,254}$');